(function(){const body=document.body;let theme='light';try{theme=localStorage.getItem('earthscope-theme')||'light'}catch(_){}if(['light','dark','night'].includes(theme))body.dataset.theme=theme;const b=document.getElementById('docs-theme');function update(){const t=body.dataset.theme||'light';b.innerHTML=(t==='light'?'☾':t==='dark'?'◐':'☀')+' <span class="theme-label">'+(t==='light'?'Dark mode':t==='dark'?'Night mode':'Light mode')+'</span>';}b.addEventListener('click',()=>{const t=body.dataset.theme||'light';const next=t==='light'?'dark':t==='dark'?'night':'light';body.dataset.theme=next;try{localStorage.setItem('earthscope-theme',next)}catch(_){}update()});update()})();
</script>
